  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255); // Blue
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 255); // Yellow
  brush.beginShape();
  brush.vertex(100, 100);
  brush.vertex(300, 100);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Hills
  brush.fill("#336633", 255); // Dark green
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 300);
  brush.endShape(true);

  // Ground
  brush.fill("#228B22", 255); // Dark green
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(200, 400);
  brush.endShape(true);
}
```

