  brush.fill("#468246", 255);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 300);
  brush.endShape(true);

  // Sun
  brush.fill("#ff4500", 255);
  brush.beginShape();
  brush.vertex(150, 150);
  brush.vertex(250, 150);
  brush.vertex(200, 100);
  brush.endShape(true);
}

