  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 255);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Hills
  brush.fill("#468246", 255);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 300);
  brush.endShape(true);

  // Sun
  brush.fill("#ff4500", 255);
  brush.beginShape();
  brush.vertex(150, 150);
  brush.vertex(250, 150);
  brush.vertex(200, 250);
  brush.endShape(true);
}

